ST.xhtml:p:
IF nVar=3 THEN(*0~180 取模*)
  LocalVar1 := LREAL_TO_DINT(ABS(InputVar));
  LocalVar2 := ABS(InputVar) - DINT_TO_LREAL(LocalVar1);
  LocalVar3 := MOD(LocalVar1,180);
  LocalVar4 := LocalVar2 + DINT_TO_LREAL(LocalVar3);
  FUN_FMOD1 := LocalVar4; 

ELSIF nVar=4 THEN
  LocalVar1 := LREAL_TO_DINT(InputVar);
  LocalVar2 := InputVar - DINT_TO_LREAL(LocalVar1);
  LocalVar3 := MOD(LocalVar1,360);
  LocalVar4 := LocalVar2 + DINT_TO_LREAL(LocalVar3);

  FUN_FMOD1 := LocalVar4;  

END_IF;
